𗣛𘟙𗯨𗙏𘝯𗖰𗚩.content:
{{header
 | title    ={{Tangut|𗣛𘟙𗯨𗙏𘝯𗖰𗚩}} (''High King Avalokitesvara Sutra'')
 | author   = 
 | section  =
 | previous = 
 | next     =
 | notes    = Tangut translation of ''Gāowáng Guānshìyīn jīng'' 高王觀世音經 [T2898]. It is preserved in a unique printed copy published during the early Ming dynasty (colophon dated 1430/1432) which is held at the Palace Museum in Beijing (cat. no. B51·002), formerly in the collection of Zhōu Zhàoxiáng 周肇祥 (1880–1954).
}}

<!--Preface (actually the background story)-->
{{Tangut|《𗣛𘟙𗯨𗙏𘝯𗖰𗚩𗿣𘉐𘁨》}}

{{Tangut|𗫈𗣛𘚻𗂧𘟙𗤀，𘈩𘓐𗦻𗐾𘊐𗷌𗥖<!--mistake for 𘏨?-->𗔇𘅫𗀔𗭊𗫻，𗫢𘅯𘔼，𘜶𘕋𘙌𘄩，𘍓𗷩𗭊𗋐，𘙌𗷝𗈶𗗟，𗾞𘈚𗅋𗏡𗳒，《𗯨𗙏𘝯𗫡𘗠𘄿》𘙇𗧯，𘈞𘇂𘈩𗗆𗖌，𘙌𘈞𗖠𗫔𘒣：「𗍳𘌽𗖰𗧯𗿣𘉐，𘓁𗮅𘟣𘂤𘌽𘏰《𗣛𘟙𗯨𗙏𘝯𗖰𗚩》𗡞𗢶𘆖𗣷，𗌭𘌽𗧹𘜤𗇘。」𘊐𗷌𘒣：「𘘮𘍓𗷩𗅁𗋐，《𗣛𘟙𗯨𗙏𘝯𗖰𗚩》𗰓𗵗𗧓？」𗖠𗫔𘒣：「𗟲𗳒𗨙𗟻𘉞。」𘙌𗒾𘃌𗢭𘊝𗢶𗋚𘆖𗫤𘜔𗷝𗣷，𘟙𘝦𘃡𗜍𗇋𘙌𘒫，𘊐𗷌𘓒𗃬，𗷘𗇋𗗙𘘣：「𗍳𘆄𗧓𗗙𗕿𘗦𗖵𗨷𘙥𘙇𗝿𗧓。」𗵘𗸕𗣐𗤖𗳒𘊝𗢶𗋚𘆖𘜔𗈪𗣷𗀔，𘟙𗿢𗖵𘗐𗜍𘘣𘟫𘖗。𘊐𗷌𘛽𘏔𘙌𗩱，𘟫𘕕𗺴𗞞𗨻，𘟙𘋩𘙌𘖉，𘟙𗏠𘛪𗳒，𘊐𗷌𗗙𗤄：「𘕣𘝦𗭍𗖵𘌽𗍊𗿣𘉐𗋚𗜓𘞌𗆤𗳒𘙇𘀽。」𘊐𗷌𘒣：「𘈞𘇂𘈩𗖠𗫔𗖌𘟀，𘘮𗗙《𗣛𘟙𗯨𗙏𘝯𗖰𗚩》𗖌𘙌𗖢𗡞𗢶𗋚𘆖𗋕𘉐𗪺𘟂。」𘟙𘊐𗷌𗗙𗁅𗼋𗡙𗜓，𘟙𘓐𗷆𗅉𗜍𗟭𘜔，𘂆𘌽𗖰𘜤𗡞𗢶𗘯𘆖𘘣，𗂧𗿢𗋚𗭍𗏡𗜍𗾺𗄊𘛽𘐠𘖑𗩱，𘌽𗍊𘈃𘍳𗠁𘉐𘟣𗖵，𗏡𘈑𘊐𗓁𘟀。}}

<!--Wishing long life to the present emperor [of the Ming dynasty]-->
{{Tangut|𗫈𗌮𘓺𘋨𗕑𗕑𗩟！}}

<!--Sutra-->
{{Tangut|《𗣛𘟙𗯨𗙏𘝯𗖰》}}

{{Tangut|𗢰𘓩𗯨𗙏𘝯𘋢𗥤。𗢰𘓩𗢳。𗢰𘓩𗹙。𗢰𘓩𗗆。𗢳𗂧𘔼𘟣，𗢳𗹙𘍦𗦫，𗏹𗴴𗧓𗑗，𘔼𘟣𗢳𗹙。𗢰𘓩𗓚𘄽𘄒𘎑𘏞𗓽𗕥，𘜶𗾈𗥺𘟂。𗢰𘓩𗓚𘄽𘄒𘎑𘏞𗓽𗕥，𘜶𗭼𗥺𘟂。𗢰𘓩𗓚𘄽𘄒𘎑𘏞𗓽𗕥，𗩾𗨁𗥺𘟂。𗢰𘓩𗓚𘄽𘄒𘎑𘏞𗓽𗕥，𘜄𗤋𘜄𗥺𘟂。}}

[[File:Tangut High King Avalokitesvara Sutra illustration.jpg|thumb|right|450px|{{Tangut|𘈞𘇂𗖠𗫔𗖰𗚩𗖢𘏚}}, {{Tangut|𘊐𗷌𗣛𘏚𘛽□□𗩱}}, {{Tangut|𗿣𘉐𘕣𘟣𘟙𘊐𗷌𗤄}}, {{Tangut|𗡞𘐳𗖰𗚩}}]]
<poem>
{{Tangut|𗢰𘓩𗑗𘉍𗓦𗤱𗢳。}}
{{Tangut|𗹙𗔇𗢳。}}
{{Tangut|𘆅𗹛𗅸𗢳。}}
{{Tangut|𗾈𗺌𗓦𘟙𗢳。}}
{{Tangut|𗢳𘒣𗍏𗓁𗧊𘟙𗢳。}}
{{Tangut|𗹙𗓑𗢳。}}
{{Tangut|𗵒𘗁𗔇𘆅𗹛𗉫𗰘𗢳。}}
{{Tangut|𘏨𗠁𗢳。}}
{{Tangut|𗩜𘘚𗋡𗍥𘉍𗢳。}}
{{Tangut|𗫡𘉍𗣼𘉐𘑗𘟙𗢳。}}
{{Tangut|𗩴𗫻𗣼𘉐𘏨𘟙𗢳。}}
{{Tangut|𗋚𗦎𗒹𗢳。}}
{{Tangut|𗷝𗆐𗾈𗑱𗡞𗢳。}}
{{Tangut|𗡞𗏁𘊝𗢳。}}
{{Tangut|𗕑𗏁𗡞𗢳。}}
{{Tangut|𗏁𘊝𗤻𗠁𗢳。}}
{{Tangut|𘊝𗦲𗵒𘗁𗔇𗢳。}}
{{Tangut|𗅆𘉍𗢳。}}
{{Tangut|𗤁𗏣𗤁𗢳𗦻𗿸。}}
{{Tangut|𘃂𗏣𘏨𘉍𗼑𗃵𗤓𗖻𗙏𘟙𗢳。}}
{{Tangut|𗑛𗏣𘕰𗺉𗤻𘟙𗢳。}}
{{Tangut|𗂰𗏣𗍥𘟙𗾈𗿣𘝡𗤻𘟙𗢳。}}
{{Tangut|𗈇𗏣𗼑𗃵𘄎𗑗𗢳。}}
{{Tangut|𗨁𗏣𘜔𗤋𘄎𗑗𘏨𗪟𗢳。}}
{{Tangut|𗤢𗏣𗩴𗘺𗼑𗙏𘟙𗢳。}}
{{Tangut|𘖑𗆄𗱕𗢳。}}
{{Tangut|𗮅𘏨𗢳。}}
{{Tangut|𗷅𗡝𘉒𗐱𗢳。}}
{{Tangut|𗓁𗱈𗢳。}}
{{Tangut|𗠝𘜇𗢳。}}
{{Tangut|𗓁𗁬𗢳。}}
{{Tangut|𘇂𗏣𗫔𘎳𗄑𗄑𗢳。}}
</poem>

{{Tangut|𗽀𗐯𗅁𗫻𗫂，𗼻𗀔𘕂𗫻，𘓁𗅉𘉏𗲠𘇂𗫻𗇋，𗫔𘎳𗄑𗄑𗗙𗕿𗪆，𘝵𗯩𘗲𗵐𗬁𗁿，𗾞𘈚𗹢𗧯，𗤶𗏹𘌽𗖰𘆖𗴿，𗌭𗢣𘎳𘍔𗈞𗩱，𗻊𗈙𗷣𗌻𗟻。}}

<poem>
{{Tangut|𗢰𘓩𘜶𗭼𗯨𗙏𘝯。}}
{{Tangut|𗭼𘝯𗯨𗙏𘝯。}}
{{Tangut|𗴀𗭼𗯨𗙏𘝯。}}
{{Tangut|𘏒𗭼𗯨𗙏𘝯。}}
{{Tangut|𗩜𘟙𘋢𗥤。}}
{{Tangut|𗩜𗨁𘋢𗥤。}}
{{Tangut|𘉏𗲠𗔇𘋢𗥤。}}
{{Tangut|𗼻𗔇𘋢𗥤。}}
{{Tangut|𗫡𘟙𗌮𗆐。}}
{{Tangut|𗤻𗠁𘋢𗥤。}}
</poem>

{{Tangut|𗆫𗆫𘌽𗖍𘆖，𗒹𗢳𗯨𗖻，𘜤𗥺𗖸𘙇𘎪：}}

{{Tangut|𘄊𘏞𘄊𘏞𘆨，𗴼𗶴𗴼𗶴𘆨，𗁬𗓽𘆵𘆨，𘆵𗶴𗓽𘆨，𘜉𘄊𘆵𘆨，𗢀<small>𗬂</small>𗶴。}}

<poem>
{{Tangut|𗰭𗏣𗯨𗙏𘝯，𗱕𘋢𗥤𗄑𗄑。}}
{{Tangut|𗡔𘓞𗫔𘎳𗥞，𗦻𘆖𗄊𗧐𗇘。}}
{{Tangut|𗼕𘞆𗇋𘟣𘅍，𘞌𗆤𘏒𘎪𗦇。}}
{{Tangut|𗧀𗦫𘔼𗫔𗇋，𗗈𘆖𗟲𗅋𗤘。}}
{{Tangut|𗖰𘆖𗡞𗢶𗣷，𗆫𗆫𗤶𗅋𗏙。}}
{{Tangut|𗜐𗟚𘐠𘖑𗩱，𘟞𘐬𘜤𗕟𗷷。}}
{{Tangut|𗕣𗔊𘚻𘅎𗄈，𗈶𗫂𗯗𗢘𗨻。}}
{{Tangut|𘌽𘅣𗏗𘅇𘘣，𗱕𗢳𘗫𗅋𘎪。}}
</poem>

{{Tangut|《𗣛𘟙𗯨𗙏𘝯𗖰𗚩》𘃪。}}

{{Tangut|
𗫈𗓁𗌮𗆐𗯨𗧊𗼕𘎳𗉛𗥓𗗙𗇐𘋢𗥤，𗫸𗜓𘕕𗐯𘚠<!--mistake for 𗅁?-->𗤼𘇂𗮔𗋕𘂤𗯨𗙏𘝯𘋢𗥤𗫂，𗡔𘓞𗓰𗾟𘜶𗗚𗋽𗑠𘜄𗩾𗴐𘍔𗥞，𗍏𗓁𘑗𗸒𗴀𗴢𗼋𗌭𘙌𗅆𗿣𗜓𗒐𗧯𗇋𗣋𘔏𗼕𘟣，𗤦𗟄𗞌𗝿<small>𗕘</small>𘅄，𗿒𗹙𘋩𗤶𗊦，𘌽𗖰𗿣𘉐𗮅𗿷𗓁𗖵𘞌𘓟𗤶𗄈，𗑗𘔮𗋚𗫋𘅤𗇋𗌽𗾤，𗆧𗣳𘟩𗀘𗡞𗩙𗱢𘟩𗱕𘈑𘋩𘈈，𘌽𗩴𗺉𗳒。}}
{{Tangut|𗥃𘘖𗄊𗱱𘕕𘟣，𗫡𘞙𗢣𘎳𘍔𗗚𗘯𗰛，𘈩𗒛𗒘𗧘𗭊𗥤，𘜶𗫨𗤓𗦫𘘢𗳒𘈬𗦺𗠁𗫴𘊐𘕥𗧀𘓞。}}
{{Tangut|𗫈𗌮𘓺𘋨𗕑𗩟𗑠𗄼𘓺𘈷𘜶𗸱𗡞𘌞！𘊐𘟀𗂧𗺉𗬢𗸁𘂀𗚉𘗐𗴴𘝞𘟫𗂸𗂅𗹐𗣼𗑠𗭍。𗅉𘓞：}}
{{Tangut|𘘖𗿷𗔀𗴺𘘂𘗐𘀄𘓄𗹙𗐯𗫻𘒻𗢳𗵘𘗐𗵆。}}

<!--Colophon with list of subscribers, dated rénzǐ cyclical year of the Ming dynasty, on the 15th day of the 1st month of the 5th year of the "sun de" (= Xuāndé) era. Xuāndé 5 was not a rénzǐ year, so this must be a mistake for either Xuāndé 5 gēngxū year (1430) or Xuāndé 7 rénzǐ year (1432).-->
{{Tangut|𘜶𗭼𗤀𗋌𘋇𗍏𘆄𗃑𗭊𗏁𗤒𘑲𗼑𗰭𗏁𗾞，𘓞𗄈𗇋𗆡𘆄𘈪𘆄𘋮𘉑𘉏𘓁𗦬𗫔𘝵𗗙𗑗𘔮𘈈𗫂𘐘𗟻𗇋：}}
{{Tangut|𗥚𗳩𗖧𘙇𘊾𗏤𗭊𗣔𗣔、𗥚𗳩𗑑𗅁𗠽𘆄、𗥚𗳩𗒔𗅁𗥰𗭊、𗥚𗳩𘞽𗆤𘙇𘅻𗫍𗣀、𘁂𗦱𗸹𘄂、𘁂𗦱𗆠𘕿𘈪𗭊、𘁂𗦱𗒮𗺑𘃳𘄱𘉒𘙇、𘁂𗦱𘄿𗕘𗯸𗅁、𗦮𗊻𗁷𗦎𗜔𗕘、𗸰𘄍𗒉、𗸰𗦗𗅾𘋮、𗸰𗥥𗃞𗗿𗆠𘕿、𘝾𗏵𗕘𘊾𗭊、𘝾𗆠𗤙𗭊、𗧓𘆄𗇞𘛵𗶃、𗧓𘆄𗢰𘁂𘆄𘄱𘉒𘙇、𗢰𗭊𗏵𘎤𗵠𘃞𘕜、𗷮𗖧𘀺、𗷮𗸰𗃞𗗿𗠽𘆄、𗦮𗕘𗆠𘕿𘄱𘉒𘙇、𗳩𘄂𗙴𗁬𘕿𗶃、𗳩𘄂𗙴𗜔𘄂、𗳩𘄂𗙴𗁬𗒉𘆄、𗳩𘄂𗙴𗔄𗆠𘊾𘆄，𗋪𗹰𗫻𗫻。}}
{{Tangut|𗹙𗐯𗅁𗹬𘟣𗄑𗄑𗌮𗫻𗿳𘂝𗧹𘂳𗖈𗼞𘅣𘞝𗢯𗯵𗹪𘓁𘛽𘒻𗿳𗀔𗩾𗴴𗑗𗂧𗅁𗘯𘎳。𗄻𗕘𗕌𘆄𗤛𗅁𘘑𘆄𗥰𗕘𘐘□。}}

==Sources==
* ''Zhōngguó cáng Xīxià wénxiàn'' 中國藏西夏文獻 = ''Tangut Manuscripts Collected in China'' Vol. 12 (Lanzhou: Gansu People’s Publishing House and Dunhuang Literature and Art Publishing House, 2005) pp. 402–408 (B51·002).

