𗵒𘗁𘄒𘎑𘏞𗓽𗕥𗸰𗖰𗚩.content:
{{header
 | title    ={{Tangut|𗵒𘗁𘄒𘎑𘏞𗓽𗕥𗸰𗖰𗚩}} (''Diamond Sutra'')
 | author   = 
 | section  = 
 | previous = 
 | next     = 
 | notes    = Tangut translation of the ''Diamond Sutra'' (Sanskrit: ''Vajracchedikā Prajñāpāramitā Sūtra''; Chinese: ''Jīngāng bōrě bōluómì jīng'' 金剛般若波羅蜜經 [T2732]). Transcription based on an almost complete woodblock printed edition recovered from a stupa near the [[:w:Mogao Caves|Mogao Caves]] at Dunhuang, now held at the Dunhuang Research Academy [G11·035], with the missing part of ch. 32 based on a fragment of a woodblock printed edition held at the Wuwei Municipal Museum in Gansu [G31·015]. This version includes the complete prose text in 32 chapters, as well as an initial section listing the incantations to be recited before reading the sutra, but omits the gāthā verses for each chapter (these verses are present in some other editions of the Tangut version of the ''Diamond Sutra'').
}}

[[File:Tangut Diamond Sutra frontispiece.jpg|thumb|right|450px|Initial illustration from G11·035]]

<!-- Initial section listing the incantations to be recited before reading the sutra-->
{{Tangut|𗓱𘓐《𗵒𘗁𗖰𗚩》𗒐𗧯，𗌭𗪘𗪟𗤶𗨳𗳒𗢸𘈽𗑗𘒣𗒘𘆖𘘦，𗅉𘉋𗵒𘗁𗥃𘋢𗥤𗦻𘆖，𗴢𗾤𗰓𗫻𘏚𘋩𗏹𗶅𗓑𘃞。}}

<!--Mantra for purifying verbal karma (淨口真言)-->
{{Tangut|𗢸𘈽𗑗𘒣𗒘：}}

{{Tangut|𘏱𘝿𘏱𘝿　𘓩𗶴𘏱𘝿　𘏱𘏱𘝿　𗢀𗬂𗶴}}

<!--Mantra for pacifying the earth (安土地真言)-->
{{Tangut|𗼻𗔁𘒮𘒣𗒘：}}

{{Tangut|𗢰𘓩　𘅄𗟦𘛵　𗑫𗁬𗽮　𗙫𘊴𘏘𘊴𘏘　𗶩𘃣　𗢀𗬂𗶴}}

<!--Mantra for making universal offering (普供養真言)-->
{{Tangut|𗄊𗴿𗒀𘒣𗒘：}}

{{Tangut|𗙫　𘕜𘕜𗢰　𘅄𗣧𗬂　𘎧𗱽𘃜　𗦀}}

<!--Invitation to the eight vajra beings (奉請八金剛)-->
{{Tangut|𘉋𗵒𘗁𗾤：}}
<poem>
{{Tangut|𗴢𗾤𗘍𗧹𗟥𗵒𘗁}}
{{Tangut|𗴢𗾤𗀀𗷰𗵒𘗁}}
{{Tangut|𗴢𗾤𗘩𗴿𗖵𗵒𘗁}}
{{Tangut|𗴢𗾤𗴂𗑗𗋽𗵒𘗁}}
{{Tangut|𗴢𗾤𘔚𗙏𗵒𘗁}}
{{Tangut|𗴢𗾤𗅆𗧹𗟥𗵒𘗁}}
{{Tangut|𗴢𗾤𗂎𗾈𗵒𘗁}}
{{Tangut|𗴢𗾤𘜶𗿣𗵒𘗁}}
</poem>

<!--Invitation to the four bodhisattvas (奉請四大菩薩)-->
{{Tangut|𗥃𘋢𗥤𗾤：}}
<poem>
{{Tangut|𗴢𗾤𗵒𘗁𗑟𘋢𗥤}}
{{Tangut|𗴢𗾤𗵒𘗁𘇗𘋢𗥤}}
{{Tangut|𗴢𗾤𗵒𘗁𘟠𘋢𗥤}}
{{Tangut|𗴢𗾤𗵒𘗁𗟲𘋢𗥤}}
</poem>

<!--Yunhe hymn (云何梵)-->
{{Tangut|𗖰𗧯𗏆𗙏：}}
<poem>
{{Tangut|𗵒𘗁𗅋𗹪𘛽，𘝶𗦜𘗽𘙲𘜘。}}
{{Tangut|𗅉𘕣𗦫𘔼𗖵，𘜶𗬢𗸁𗪺𘜘。}}
{{Tangut|𘝶𗦜𗖰𗚩𗖵，𗩾𘃪𗳌𘋟𗫡。}}
{{Tangut|𘓞𗢳𗤓𗓦𘏒，𗾟𘋢𗋐𘔼𘎪。}}
</poem>

<!--Votive text (發願文)-->
{{Tangut|𘓞𗄈𘝞：}}
<poem>
{{Tangut|𗰭𗏣𘖑𗆄𗢳，𗵣𗖖𘕕𗐯𗖻。}}
{{Tangut|𗧓𗫈𘜶𘓞𗄈，𘌽𗵒𘗁𗖰𗧯。}}
{{Tangut|𗨁𗱱𗥃𗊢𘘖，𗤢𗥞𘕕𘊄𘍔。}}
{{Tangut|𗓁𘟀𗇋𘟣𗫂，𘏞𘛛𗤶𗭊𗄈。}}
{{Tangut|𘌽𘈩𘛽𗱱𗋃，𗩾𗴴𗯮𗘯𘎳。}}
</poem>

