<!--Chapter 4 (妙行無住分第四)-->
{{Tangut|《𗤓𘝦𗫻𗤋𘊲𗥃𗡪》}}

{{Tangut|「𗅉𘐡𗍏𘏞𘛛，𘋢𗥤𗹙𘕿𗫻𗦇𗅋𗳒𗅖𘈈𗭍𗦇，𘌽𗫂𗩨𘕿𗅋𗫻𗅔𘈈，𗙏、𗡎、𘕉、𘄩、𗹙𘕿𗅋𗫻𗅖𘈈。𗍏𘏞𘛛，𘋢𗥤𘌽𗍊𗅖𘈈，𘍦𘕿𗅋𗫻𗦇。𘝶𗦜𘃞？𗓱𘋢𗥤𘍦𘕿𗅋𗫻𗅖𘈈，𗌭𗼕𗣼𗅢𗦢𘏚𗤋。𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𘃂𗏣𘉏𗲠𗅢𗦢𘏚𗈪𗁁？」}}

{{Tangut|「𗅋𘃞，𗯨𗖻。」}}

{{Tangut|「𗍏𘏞𘛛，𗑛、𗂰、𗈇𗏣，𗥃𘕴𗨁𗯴，𘉏𗲠𘂆𗅢𗦢𘏚𗈪𗁁？」}}

{{Tangut|「𗅋𘃞，𗯨𗖻。」}}

{{Tangut|「𗍏𘏞𘛛，𘋢𗥤𘍦𗅋𗫻𗅖𘈈𗼕𗣼，𘂆𗋕𗑠𗈪𗅲，𗅢𗦢𘏚𗤋。𗍏𘏞𘛛，𘋢𗥤𗧀𘘝𗖵𗫻𗦇。」}}

[[Category:𗼇𗟲]]
[[Category:Buddhist texts in Tangut]]

