<!--Chapter 9 (一切無相分第九)-->
{{Tangut|《𗄑𗄑𘍦𗤋𘊲𗢭𗡪》}}

{{Tangut|「𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𗍏𗁬𗙔𘌽𗍊𗆫𘃡：『𗧓𗍏𗁬𗙔𗫴𗵗𗧓𗈪』𘘣。」}}

{{Tangut|𗍏𘏞𘛛𘒣：「𗅋𘃞，𗯨𗖻。𘝶𗦜𘃞？𗍏𗁬𗙔𗫂𗪘𘃽𘘣，𘃽𗦇𗤋𘃞。𗩨、𗙏、𗡎、𘕉、𘄩、𗹙，𘕿𗅋𘃽，𗌭𗍏𗁬𗙔𗦻𗨻。」}}

{{Tangut|「𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𗬐𗁬𗱔𘌽𗍊𗆫𘃡：『𗧓𗬐𗁬𗱔𗫴𗵗𗧓𗈪』𘘣。」}}

{{Tangut|𗍏𘏞𘛛𘒣：「𗅋𘃞，𗯨𗖻。𘝶𗦜𘃞？𗬐𗁬𗱔𗫂𘈩𗄼𘞓𘘣，𘞌𗄼𘞓𗤋，𗌭𗬐𗁬𗱔𗦻𗨻。」}}

{{Tangut|「𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𗠝𗅾𗱔𘌽𗍊𗆫𘃡：『𗧓𗠝𗅾𗱔𗫴𗵗𗧓𗈪』𘘣。」}}

{{Tangut|𗍏𘏞𘛛𘒣：「𗅋𘃞，𗯨𗖻。𘝶𗦜𘃞？𗠝𗅾𗱔𗫂𗅋𗆮𘘣，𘞌𗅋𗆮𗦇𗤋，𗌭𘌽𘔼𗠝𗅾𗱔𗦻𗨻。」}}

{{Tangut|「𗍏𘏞𘛛：𗉣𘕿𘝶𗦜？𗠝𗓽𘂦𘌽𗍊𗆫𘃡：『𗧓𗠝𗓽𘂦𗵘𗵗𗧓𗈪』𘘣。」}}

{{Tangut|𗍏𘏞𘛛𘒣：「𗅋𘃞，𗯨𗖻。𘝶𗦜𘃞？𗠝𗓽𘂦𘘣𗦇𘞌𗹙𗅋𘟣。𗯨𗖻，𗓱𗠝𗓽𘂦𘌽𗍊𗆫𘃡：『𗧓𗠝𗓽𘂦𗵘𗵗𗧓』𘘣，𗌭𗧓、𘓐、𘋢𗋐、𗤷𗇋𘕿𗂆𘟂。𗯨𗖻，𗢳𗧓𗗙𗉜𗤋𘋅𗁲𘜘𗇋𘂤𗩾𗨁𗡪𗨻，𗨁𗡪𗧠𗈜𗠝𗓽𘂦𘟂𘘣。𗯨𗖻，𗧓𗧠𗈜𗠝𗓽𘂦𘟂。𗧓𘘣𘌽𗍊𗆫𗅋𗣬𗧓。𗯨𗖻，𗧓𗓱𘌽𗍊𗆫𘃡：『𗠝𗓽𘂦𗵘𗵗𗧓』𘘣𗧓，𗌭𗯨𗖻，𗍏𘏞𘛛𗠝𗱞𗅾𘝦𘟠𗇋𘟂𗅋𘘣。𗍏𘏞𘛛𘞌𗭍𗦇𗤋𗖵，𗍏𘏞𘛛𗠝𗱞𗅾𘝦𗳘𗇋𘟂𘘣。」}}

