<!--Chapter 10 (莊嚴淨土分第十)-->
{{Tangut|《𗑗𗂧𗡮𘆡𘊲𗰗𗡪》}}

{{Tangut|𗢳𗍏𘏞𘛛𗗙𘘣：「𗉣𘕿𘝶𗦜？𗌮𗆐𗟷𗖏𗉃𘐂𗢳𘋩𗫻𘝨，𗹙𘕿𘜘𗦇𗈪𘟣？」}}

{{Tangut|「𗅋𘃞，𗯨𗖻。𗌮𗆐𗉃𘐂𗢳𘋩𗫻𘝨，𗹙𘕿𘞌𘜘𗦇𗤋。」}}

{{Tangut|「𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𘋢𗥤𗢳𗂧𗈪𗡮𘆡？」}}

{{Tangut|「𗅋𘃞，𗯨𗖻。𘝶𗦜𘃞？𗢳𗂧𗵽𘆡𗫂𗵽𘆡𗅔，𗌭𗵽𘆡𗦻𗨻。𘌽𘔼𗍏𘏞𘛛，𗱕𘏞𗢈𗓚𘄽𗢈𘌽𗍊𘄎𗑗𗤶𗄈，𗩨𗫻𗤶𗅋𗄈，𗙏、𗡎、𘕉、𘄩、𗹙𗫻𗤶𗅋𗄈，𗫻𗦇𗤋𗤶𗄈𗦇。」}}

{{Tangut|「𗍏𘏞𘛛，𘊛𘓐𘛽𗍏𗓁𘑗𘟙𗰣，𗉣𘕿𘝶𗦜？𗋕𘛽𗈪𘜶𘃞？」}}

{{Tangut|𗍏𘏞𘛛𘒣：「𘜶𘃞，𗯨𗖻。𘝶𗦜𘃞？𗢳𘛽𗅔𗗙𘜶𘛽𘟂𘘣。」}}

