<!--Chapter 17 (究竟無我分第十七)-->
{{Tangut|《𗩾𘃪𗧓𗤋𘊲𗰗𗒹𗡪》}}

{{Tangut|𗉘𘝨𗍏𘏞𘛛𗢳𗗙𘒣𘘣：「𗯨𗖻，𗩴𗾖𘈷、𗩴𗡸𘓐，𗠝𗷧𗸰𗓽𘋅𗴥𘋅𘏞𘛛𗤶𗄈𘅍，𘝶𗦜𘗲𗫻？𘝶𗦜𘀟𗤶𘛥𗌻𗦇？」}}

{{Tangut|𗢳𗍏𘏞𘛛𗗙𘘣：「𗩴𗾖𘈷、𗩴𗡸𘓐，𗠝𗷧𗸰𗓽𘋅𗴥𘋅𘏞𘛛𗤶𗄈𘅍，𘌽𗍊𗤶𗄈，𗧓𘋢𗋐𗄑𗄑𗗙𗌗𗰛𗠔，𗧓𘋢𗋐𗄑𗄑𗗙𗌗𗰛𘃪，𗅉𘋢𗋐𘞪𗖌𗰣𘞌𗌗𗰛𗇋𗤋𘘣𗦇。𘝶𗦜𘃞？𗓱𘋢𗥤𗧓𘍦、𘓐𘍦、𘋢𗋐𘍦、𗤷𗇋𘍦𘟣，𗌭𘋢𗥤𗅔。𘌽𗫂𘝶𗦜？𗍏𘏞𘛛，𗠝𗷧𗸰𗓽𘋅𗴥𘋅𘏞𘛛𗤶𗄈𗇋𘞌𗹙𗅋𘟣𘃞。𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𗌮𗆐𗋕𗉃𘐂𗢳𘋩𗠝𗷧𗸰𗓽𘋅𗴥𘋅𘏞𘛛𘜘𗭪𗹙𗈪𗟧？」}}

{{Tangut|「𗅋𘃞，𗯨𗖻。𗧓𗢳𘙇𘎪𗧘𗈪𗥤𗧓𗖵，𗢳𗋕𗉃𘐂𗢳𘋩𗠝𗷧𗸰𗓽𘋅𗴥𘋅𘏞𘛛𘜘𗇋𗹙𗅋𘟣。」}}

{{Tangut|𗢳𘒣：「𘟂𘃞，𘟂𘃞。𗍏𘏞𘛛，𗌮𗆐𗠝𗷧𗸰𗓽𘋅𗴥𘋅𘏞𘛛𘜘𘞌𗹙𗅋𘟣。𗍏𘏞𘛛，𗓱𗌮𗆐𗠝𗷧𗸰𗓽𘋅𗴥𘋅𘏞𘛛𘜘𗇋𗹙𘟣，𗌭𗋕𗉃𘐂𗢳𗧓𗗙𘐆𗒐，𗍳𗏡𗢳𗨻，𗦻𗫂𗷅𗡝𘉒𗐱𗅋𘘣；𗠝𗷧𗸰𗓽𘋅𗴥𘋅𘏞𘛛𘜘𘞌𗹙𗅋𘟣，𘌽𘔼𗉃𘐂𗢳𗧓𗗙𘐆𗒐，𗍳𗏡𗢳𗨻，𗦻𗫂𗷅𗡝𘉒𗐱𘘣。𘝶𗦜𘃞？𗌮𗆐𗫂，𗱕𗹙𗌮𗧘𘟂。𗓱𘓐𗌮𗆐𗗙𗠝𗷧𗸰𗓽𘋅𗴥𘋅𘏞𘛛𗟧𘘣𗫂。𗍏𘏞𘛛，𗢳𗠝𗷧𗸰𗓽𘋅𗴥𘋅𘏞𘛛𘜘𘞌𗹙𗅋𘟣。𗍏𘏞𘛛，𗌮𗆐𗐗𘜘𗠝𗷧𗸰𗓽𘋅𗴥𘋅𘏞𘛛，𗳱𘂤𘞌𗤋𗏗𗤋。𘌽𘔼𗌮𗆐𗹙𗄑𗄑𗄊𗢳𗹙𘟂𘘣。𗍏𘏞𘛛，𗹙𗄑𗄑𘘣𗫂，𗹙𗄑𗄑𗅔，𗌭𘌽𘔼𗹙𗄑𗄑𗦻𗨻。𗍏𘏞𘛛，𘊛𘓐𘛽𘙲𘜶𗍊。」}}

{{Tangut|𗍏𘏞𘛛𘒣：「𗯨𗖻，𗌮𗆐𘓐𘛽𘙲𘜶𗗙𘜶𘛽𗅔，𘜶𘛽𗦻𗨻。」}}

{{Tangut|「𗍏𘏞𘛛，𘋢𗥤𘂆𗋕𗑠𗈪𗅲，𗓱𘌽𗍊𘒣𘘣：『𗧓𘖑𗆄𘋢𗋐𗗙𗌗𗰛𗧓』𘘣，𗌭𘋢𗥤𗅋𘘣。𘝶𗦜𘃞？𗍏𘏞𘛛，𘋢𗥤𘘣𗦇𘞌𗹙𗅋𘟣。𘌽𘔼𗯨𗖻𗹙𗄑𗄑𗧓𗤋、𘓐𗤋、𘋢𗋐𗤋、𗤷𗇋𗤋𘘣。𗍏𘏞𘛛，𗓱𘋢𗥤𘌽𗍊𘒣𘘣：『𗧓𗢳𗂧𗵽𘆡𗧓』𘘣，𘂆𘋢𗥤𗅋𘘣。𘝶𗦜𘃞？𗌮𗆐𗢳𗂧𗵽𘆡𗫂，𗵽𘆡𗅔，𗌭𗵽𘆡𗦻𗨻𘘣。𗍏𘏞𘛛，𗓱𘋢𗥤𗧓𗹙𗤋𗥤，𗌭𗌮𗆐𗳱𗗙𘋢𗥤𗒘𘟂𘘣。」}}

