<!--Chapter 21 (非說所說分第二十一)-->
{{Tangut|《𘎪𘎪𗦇𗅔𘊲𗍫𗰗𘈩𗡪》}}

{{Tangut|「𗍏𘏞𘛛，𗍳𗌮𗆐𘌽𗍊𗆫𘃡：『𗧓𘎪𗦇𗹙𘟣』𘘣。𘅇𘘣𘉞。𘌽𗆫𘅇𗣬。𘝶𗦜𘃞？𗓱𘓐𗌮𗆐𘎪𗦇𗹙𘟣𘘣，𗌭𗢳𗗙𘊋𗨻，𗧓𘙇𘎪𗥤𘖑𗩱𘃞。𗍏𘏞𘛛，𗹙𘎪𗫂𘎪𗦇𗹙𗤋，𗌭𗹙𘎪𗦻𗨻。」}}

{{Tangut|𗉘𘝨𘟛𗤷𗍏𘏞𘛛𗢳𗗙𘒣𘘣：「𗯨𗖻，𗓱𘋢𗋐𘟣𗷝𗆐𘗽𘕿𘌽𗹙𗓁𘅍，𘓟𗤶𗄈𗈪𗩱？」}}

{{Tangut|𗢳𘒣：「𗍏𘏞𘛛，𗋕𘋢𗋐𗅔，𗅋𘋢𗋐𗅔。𘝶𗦜𘃞？𗍏𘏞𘛛，𘋢𗋐𘋢𗋐𗫂，𗌮𗆐𘋢𗋐𗅔，𗌭𘋢𗋐𗦻𗨻𘘣。」}}

