<!--Chapter 26 (法身非相分第二十六)-->
{{Tangut|《𗹙𘛽𘍦𗅔𘊲𗍫𗰗𗤁𗡪》}}

{{Tangut|「𗍏𘏞𘛛，𗉣𘕿𘝶𗦜？𘕕𗰗𗍫𘍦𗳒𗌮𗆐𘝯𘏚𗈪𗁁？」}}

{{Tangut|𗍏𘏞𘛛𘒣：「𘟂𘃞，𘟂𘃞。𘕕𗰗𗍫𘍦𗳒𗌮𗆐𗗙𘝯。」}}

{{Tangut|𗢳𘒣：「𗍏𘏞𘛛，𗓱𘕕𗰗𗍫𘍦𗳒𗌮𗆐𘝯，𗌭𘚢𘈧𗼃𘟙𘂆𗌮𗆐𘟂𗗂！」}}

{{Tangut|𗍏𘏞𘛛𗢳𗗙𘒣𘘣：「𗯨𗖻，𗧓𗢳𘙇𘎪𗧘𗈪𗥤𗧓𗖵，𘕕𗰗𗍫𘍦𗳒𗌮𗆐𗗙𗅋𘝯𗦇𘃞。」}}

{{Tangut|𗉘𘝨𗯨𗖻𗖍𘒣𘙇𘎪：}}

<poem>
{{Tangut|𗩨𗳒𗧓𘟀𗧠，𗙏𗳒𗧓𗴿𗌭。}}
{{Tangut|𗋕𘓐𗹏𗵘𗭍，𗌮𗆐𘟂𘖑𗩱。}}
</poem>

